// Rational-number library implemented with plain Number arithmetic
// (numerator/denominator pairs + gcd). BigInt is intentionally not used.

function gcd(a, b) {
  a = Math.abs(a);
  b = Math.abs(b);
  while (b !== 0) {
    const t = b;
    b = a % b;
    a = t;
  }
  return a;
}

export class Fraction {
  constructor(numerator, denominator = 1) {
    if (denominator === 0) {
      throw new Error('ZeroDivisionError: Fraction(' + numerator + ', 0)');
    }
    let num = numerator;
    let den = denominator;
    // Keep the sign on the numerator; denominator is always positive.
    if (den < 0) {
      num = -num;
      den = -den;
    }
    const g = gcd(num, den);
    this.num = num / g;
    this.den = den / g;
  }

  static fromInt(n) {
    return new Fraction(n, 1);
  }

  add(other) {
    return new Fraction(this.num * other.den + other.num * this.den,
      this.den * other.den);
  }

  mul(other) {
    return new Fraction(this.num * other.num, this.den * other.den);
  }

  div(other) {
    return new Fraction(this.num * other.den, this.den * other.num);
  }

  reciprocal() {
    return new Fraction(this.den, this.num);
  }

  gt(other) {
    return this.num * other.den > other.num * this.den;
  }

  toString() {
    return this.den === 1 ? `${this.num}` : `${this.num}/${this.den}`;
  }
}

