// cli.mjs — argparse-style command-line parser for six required integer options.
// Pure Node.js ESM, zero dependencies.

const OPTION_NAMES = ['a', 'b', 'c', 'd', 'e', 'f'];

function usageLine(progName) {
  return `usage: ${progName} [-h] --a A --b B --c C --d D --e E --f F`;
}

function errorExit(progName, message) {
  process.stderr.write(usageLine(progName) + '\n');
  process.stderr.write(`${progName}: error: ${message}\n`);
  process.exit(2);
}

function printHelp(progName) {
  const lines = [
    usageLine(progName),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
  ];
  for (const name of OPTION_NAMES) {
    const upper = name.toUpperCase();
    lines.push(`  --${name} ${upper}`);
  }
  process.stdout.write(lines.join('\n') + '\n');
  process.exit(0);
}

// Mimic Python int(): optional surrounding whitespace, optional +/- sign, then digits.
const INT_PATTERN = /^\s*[+-]?\d+\s*$/;

function parseIntArg(progName, optionFlag, raw) {
  if (!INT_PATTERN.test(raw)) {
    errorExit(progName, `argument ${optionFlag}: invalid int value: '${raw}'`);
  }
  return parseInt(raw, 10);
}

export function parseArgs(argv, progName) {
  const values = {};
  const extras = [];

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      printHelp(progName);
    }

    let name = null;
    let inlineValue = null;

    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(2, eq);
        inlineValue = token.slice(eq + 1);
      } else {
        name = token.slice(2);
      }
    }

    if (name !== null && OPTION_NAMES.includes(name)) {
      let raw;
      if (inlineValue !== null) {
        raw = inlineValue;
      } else {
        if (i + 1 >= argv.length) {
          errorExit(progName, `argument --${name}: expected one argument`);
        }
        raw = argv[i + 1];
        i += 1;
      }
      values[name] = parseIntArg(progName, `--${name}`, raw);
    } else {
      extras.push(token);
    }

    i += 1;
  }

  if (extras.length > 0) {
    errorExit(progName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  const missing = OPTION_NAMES.filter((n) => !(n in values));
  if (missing.length > 0) {
    errorExit(
      progName,
      `the following arguments are required: ${missing.map((n) => `--${n}`).join(', ')}`
    );
  }

  return {
    a: values.a,
    b: values.b,
    c: values.c,
    d: values.d,
    e: values.e,
    f: values.f,
  };
}

