19	    '',
20	    'options:',
21	    '  -h, --help  show this help message and exit',
22	  ];
23	  for (const name of OPTION_NAMES) {
24	    const upper = name.toUpperCase();
25	    lines.push(`  --${name} ${upper}`);
26	  }
27	  process.stdout.write(lines.join('\n') + '\n');
